reminderCandidateSupplement.query:
SELECT jsonb_build_object(
'observed_at', statement_timestamp(),
'columns', (SELECT coalesce(jsonb_agg(jsonb_build_object('table',table_name,'column',column_name)),'[]'::jsonb) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('reminders','family_reminders') AND column_name IN ('autopilot_origin','autopilot_card_id')),
'atomic_writer_functions', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid))),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('create_card_family_reminder','create_card_legacy_reminder','create_card_legacy_reminder_service'))
) AS metadata;
